import React from "react";
import { BrowserRouter as Router, Routes, Route, Navigate } from "react-router-dom";
import { AuthPage, ProfilePage, OCRPage, BillProcessingPage, EmployeeBillUpload, ManagerDashboard, ManagerDashboardNew, ProtectedRoute } from "./components";
import PreciseBillParser from "./components/PreciseBillParser";
import OCRSpaceBillUpload from "./components/OCRSpaceBillUpload";
import "./styles.css";

function App() {
  return (
    <Router>
      <div className="App">
        <Routes>
          {/* Public Routes */}
          <Route path="/login" element={<AuthPage />} />
          <Route path="/register" element={<AuthPage />} />

          {/* Protected Routes */}
          <Route 
            path="/profile" 
            element={
              <ProtectedRoute>
                <ProfilePage />
              </ProtectedRoute>
            } 
          />
          {/* OCR route removed for employees; OCR is integrated into Bill Processing */}
          <Route 
            path="/bills" 
            element={
              <ProtectedRoute>
                <BillProcessingPage />
              </ProtectedRoute>
            } 
          />
          <Route 
            path="/upload-bill" 
            element={
              <ProtectedRoute>
                <EmployeeBillUpload />
              </ProtectedRoute>
            } 
          />
          <Route 
            path="/team-bills" 
            element={
              <ProtectedRoute>
                <ManagerDashboardNew />
              </ProtectedRoute>
            } 
          />
          <Route 
            path="/precise-parser" 
            element={
              <ProtectedRoute>
                <PreciseBillParser />
              </ProtectedRoute>
            } 
          />
          <Route 
            path="/ocr-space-upload" 
            element={
              <ProtectedRoute>
                <OCRSpaceBillUpload />
              </ProtectedRoute>
            } 
          />

          {/* Default redirect */}
          <Route path="/" element={<Navigate to="/login" replace />} />
          <Route path="*" element={<Navigate to="/login" replace />} />
        </Routes>
      </div>
    </Router>
  );
}

export default App;
